# -*- coding: utf-8 -*-
"""Rich Vietnamese culinary knowledge base, regional synonyms, and curated Q&A memory."""

from __future__ import annotations

from typing import Any


def kb(
    topic: str,
    category: str,
    title: str,
    keywords: str,
    content: str,
    substitution: dict[str, Any] | None = None,
    priority: int = 10,
) -> dict[str, Any]:
    return {
        "topic": topic,
        "category": category,
        "title": title,
        "keywords_text": keywords,
        "content": content,
        "substitution": substitution,
        "priority": priority,
    }


